// Joins the generated map (tools/embedding-map/build.py) with the project content at build time.
// The map is regenerated by hand, so either side can be ahead of the other.

interface MapFile {
  projects: readonly { slug: string; xyz: number[] }[];
  tools: readonly { name: string; projects: readonly string[]; xyz: number[] }[];
}

/**
 * Keeps the map points whose project exists and points the tools at them. A project the map does
 * not have yet (missing) and a point whose project is gone (unknown) are left off instead of
 * failing the build: a new project builds right away and joins the map when build.py runs again.
 */
export function joinMap<P extends { slug: string }>(map: MapFile, content: readonly P[]) {
  const bySlug = new Map(content.map((p) => [p.slug, p]));
  const points = map.projects.filter((point) => bySlug.has(point.slug));
  const index = new Map(points.map((point, i) => [point.slug, i]));
  return {
    projects: points.map((point) => ({ ...bySlug.get(point.slug)!, xyz: point.xyz })),
    tools: map.tools
      .map((tool) => ({
        name: tool.name,
        projects: tool.projects.filter((slug) => index.has(slug)).map((slug) => index.get(slug)!),
        xyz: tool.xyz,
      }))
      .filter((tool) => tool.projects.length > 0),
    missing: content.filter((p) => !index.has(p.slug)).map((p) => p.slug),
    unknown: map.projects.filter((point) => !bySlug.has(point.slug)).map((point) => point.slug),
  };
}
